import {nameParts,metadata} from './inline-typography.mjs';
import {createFirstLevelQuiz} from './first-level-quiz.mjs';
import {createHoverOverview} from './hover-overview.mjs';
import {chinaMiscQuizzes} from './china-misc-definitions.mjs';
const element=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;},state=name=>['boolean',['feature-state',name],false];
export function createChinaMiscQuiz(map,host,{sidebar,tab,addPicker,native,ready}){
 const games=new Map();let current,chosen=chinaMiscQuizzes[0].id,data,loading;
 const load=()=>data?Promise.resolve(data):loading??=fetch('data/quiz/china-misc.json').then(r=>{if(!r.ok)throw Error('Quiz list could not load. Open this category again to retry.');return r.json();}).then(value=>data=value).finally(()=>loading=null);
 function mount(pack){
  const prefix='cn-'+pack.id,key='quiz-'+prefix;let quiz,preview=false,previewSaved,hover,reviewed;
  const records=()=>data?.records.filter(r=>r.parent===pack.id)||[],bounds=()=>{const pool=records();return[[Math.min(...pool.map(r=>r.center[0]))-2,Math.min(...pool.map(r=>r.center[1]))-2],[Math.max(...pool.map(r=>r.center[0]))+2,Math.max(...pool.map(r=>r.center[1]))+2]];};
  const overviewBounds=()=>pack.id==='misc-poet-birthplaces'?native.homeBounds():bounds();
  const remove=()=>{hover?.clear();if(map.getLayer(key+'-dots'))map.removeLayer(key+'-dots');if(map.getSource(key))map.removeSource(key);reviewed=null;};
  function install(){remove();map.addSource(key,{type:'geojson',promoteId:'id',data:{type:'FeatureCollection',features:records().map(r=>({type:'Feature',properties:{id:r.id},geometry:{type:'Point',coordinates:r.center}}))}});const emphasis=['any',state('quizTarget'),state('review')];map.addLayer({id:key+'-dots',type:'circle',source:key,paint:{'circle-radius':['interpolate',['linear'],['zoom'],3,['case',emphasis,7,4.5],10,['case',emphasis,10,7]],'circle-color':['case',state('quizCorrect'),'#548165',state('quizWrong'),'#b44737',state('quizTarget'),'#d4ad55','#705c46'],'circle-stroke-color':'#fff','circle-stroke-width':1.5}});}
  function pick(point){if(!map.getLayer(key+'-dots'))return null;const[x,y]=point.x===undefined?point:[point.x,point.y],hits=map.queryRenderedFeatures([[x-12,y-12],[x+12,y+12]],{layers:[key+'-dots']});let best=null,distance=Infinity;for(const f of hits){const p=map.project(f.geometry.coordinates),d=Math.hypot(x-p.x,y-p.y);if(d<distance){best=f.properties.id;distance=d;}}return best;}
  const mark=(r,value)=>{if(map.getSource(key))map.setFeatureState({source:key,id:r.id},value);};
  const setActive=value=>{document.getElementById('map-shell').dataset.quizOverlay=String(value);};
  async function fit({target}={}){if(!target){if(document.getElementById(prefix+'-quiz-type').value==='find')await window.AtlasSheet?.collapse();return host.fit(overviewBounds(),6,{manual:true,overview:false});}const[lon,lat]=target.center,cos=Math.cos(lat*Math.PI/180);let nearest=Infinity;for(const r of records())if(r.id!==target.id)nearest=Math.min(nearest,Math.hypot((r.center[0]-lon)*cos,r.center[1]-lat));const zoom=Math.min(9,Math.max(4.5,Math.log2(40*360*cos/(512*nearest)))),w=map.getContainer().clientWidth,h=map.getContainer().clientHeight,dx=w/8*360/(512*2**zoom),dy=dx*cos*h/w;return host.fit([[lon-dx,lat-dy],[lon+dx,lat+dy]],zoom,{manual:true,overview:false});}
  quiz=createFirstLevelQuiz(map,host,{country:'china',sidebar,tab,prefix,overlay:true,attachTab:false,returnPanelId:prefix+'-quiz-panel',config:{level:3,title:pack.label+' quiz',plural:pack.plural,singular:pack.singular,scopeLabel:'Quiz',scopes:[{id:pack.id,label:pack.label}],...(pack.id==='misc-poet-birthplaces'?{findInstruction:"Click this poet's birthplace on the map.",nameInstruction:'Name the poets whose birthplaces are marked.',identifyInstruction:'Name the poet born at the highlighted locality.'}:{})},storageKey:()=> 'china:'+pack.id,records,ready:()=>!!data&&ready(),fillLayers:[],lineLayer:'province-lines',capture:native.capture,hideLabels:native.hideLabels,fitScope:fit,
   async begin(){await load();await native.begin();install();},onActiveChange:()=>setActive(quiz.active),mark,pick,review(r){if(reviewed&&reviewed!==r?.id)mark({id:reviewed},{review:false});reviewed=r?.id;if(r)mark(r,{review:true});},restore(saved){remove();return native.restore(saved);}
  });
  quiz.panel.querySelector('#'+prefix+'-quiz-scope').parentElement.hidden=true;
  const topicLabel=element('label','Quiz','field-label'),topic=document.createElement('select');topic.id=prefix+'-topic';topicLabel.htmlFor=topic.id;for(const p of chinaMiscQuizzes)topic.append(new Option(p.label,p.id));topic.value=pack.id;topic.onchange=()=>controller.open({scope:topic.value});topicLabel.append(topic);quiz.panel.querySelector('[data-q=scope-label]').after(topicLabel);addPicker(quiz.panel,prefix+'-category');
  const coverage=element('details',null,'city-quiz-coverage'),list=element('ul'),sources=element('p',null,'quiz-note');coverage.append(element('summary',pack.label+' included'),element('p',pack.description,'quiz-note'),list,sources);quiz.panel.querySelector('[data-q=start]').before(coverage);
  function renderCoverage(){coverage.querySelector('summary').textContent=pack.label+' included ('+records().length+')';list.replaceChildren(...records().map(r=>(()=>{const item=nameParts(element('li'),r.en,r.local),details=element('small');metadata(details,[r.period,r.answerDetail,r.note]);item.append(document.createElement('br'),details);return item;})()));sources.replaceChildren();const links=new Map();for(const r of records())for(const source of r.references||[])links.set(source.url,source.label);for(const[url,label]of links){const a=element('a',label);a.href=url;a.target='_blank';a.rel='noopener';sources.append(a,document.createTextNode(' · '));}}
  const previewButton=element('button','Preview','quiz-text-button');previewButton.type='button';previewButton.dataset.miscPreviewStart='';quiz.panel.querySelector('[data-q=start]').before(previewButton);
  const previewPanel=element('div');previewPanel.hidden=true;previewPanel.dataset.miscPreview='';const back=element('button','Back to quiz','quiz-primary');back.type='button';back.dataset.miscPreviewEnd='';previewPanel.append(element('h2','Preview'),element('p','Hover over or tap a dot to see its name, historical context and location.','quiz-note'),back);quiz.panel.append(previewPanel);
  if(pack.id==='misc-silk-road'){for(const parent of [previewPanel,quiz.panel.querySelector('[data-q=round]')]){const box=element('div',null,'quiz-map-views');box.setAttribute('role','group');box.setAttribute('aria-label','Map view');for(const[label,getBounds]of [['All sites',bounds],['Central Asia',()=>[[70,38],[82,46]]]]){const button=element('button',label,'quiet-button');button.type='button';button.onclick=()=>void host.fit(getBounds(),7,{manual:true,overview:false});box.append(button);}if(parent===previewPanel)back.before(box);else parent.querySelector('[data-q=instruction]').after(box);}}
  const error=element('p',null,'quiz-note');error.hidden=true;error.setAttribute('role','status');quiz.panel.querySelector('[data-q=setup]').append(error);
  hover=createHoverOverview(map,{id:key+'-preview-hover',blocked:()=>!preview,resolve:point=>{const r=records().find(r=>r.id===pick(point));return r?{en:r.en,local:r.local,kind:r.answerDetail+' · '+r.period}:null;}});map.on('click',event=>{if(preview)hover.show(event.point);});
  async function endPreview(){if(!preview)return;await host.stopCamera?.();preview=false;remove();setActive(false);host.setQuizActive(false);delete sidebar.dataset.quiz;for(const b of sidebar.querySelectorAll('.panel-tabs button'))b.disabled=false;document.getElementById('home').textContent=previewSaved.home;document.getElementById('map-hint').textContent=previewSaved.hint;await native.restore(previewSaved.adapter);for(const section of sidebar.querySelectorAll('.sidebar-scroll > section'))section.hidden=section!==quiz.panel;quiz.panel.hidden=false;for(const b of sidebar.querySelectorAll('.panel-tabs button'))b.setAttribute('aria-pressed',String(b===tab));tab.setAttribute('aria-controls',quiz.panel.id);previewPanel.hidden=true;quiz.panel.querySelector('[data-q=setup]').hidden=false;quiz.setup();window.AtlasSheet?.expand();previewButton.focus({preventScroll:true});}
  previewButton.onclick=async()=>{if(quiz.active||preview)return;previewButton.disabled=true;try{await load();previewSaved={adapter:native.capture(),home:document.getElementById('home').textContent,hint:document.getElementById('map-hint').textContent};await native.begin();install();preview=true;setActive(true);native.hideLabels();host.setQuizActive(true);for(const section of sidebar.querySelectorAll('.sidebar-scroll > section'))section.hidden=section!==quiz.panel;quiz.panel.hidden=false;for(const b of sidebar.querySelectorAll('.panel-tabs button')){b.disabled=b!==tab;b.setAttribute('aria-pressed',String(b===tab));}tab.setAttribute('aria-controls',quiz.panel.id);quiz.panel.querySelector('[data-q=setup]').hidden=true;previewPanel.hidden=false;sidebar.dataset.quiz='true';document.getElementById('home').textContent='End preview';document.getElementById('map-hint').textContent='Explore '+pack.label.toLowerCase();await window.AtlasSheet?.collapse();await host.fit(overviewBounds(),6,{manual:true,overview:false});back.focus({preventScroll:true});}catch(e){if(preview)await endPreview();else{remove();if(previewSaved)await native.restore(previewSaved.adapter);}error.textContent=e.message;error.hidden=false;}finally{previewButton.disabled=false;}};back.onclick=()=>void endPreview();
  return{get active(){return quiz.active||preview;},get overlay(){return true;},get panel(){return quiz.panel;},scope:pack.id,open(options={}){quiz.open({...options,scope:pack.id});error.hidden=true;void load().then(()=>{quiz.setup();renderCoverage();}).catch(e=>{error.textContent=e.message;error.hidden=false;});},labels:()=>{if(!preview)quiz.labels();},end:()=>preview?endPreview():quiz.end(),fit:()=>preview?host.fit(overviewBounds(),6,{manual:true,overview:false}):quiz.fit()};
 }
 const controller={get active(){return !!current?.active;},get overlay(){return true;},get panel(){return current?.panel;},get scope(){return current?.scope||chosen;},open(options={}){if(current?.active)return;chosen=chinaMiscQuizzes.some(p=>p.id===options.scope)?options.scope:chosen;for(const game of games.values())game.panel.hidden=true;current=games.get(chosen);if(!current){current=mount(chinaMiscQuizzes.find(p=>p.id===chosen));games.set(chosen,current);}current.open(options);},labels:()=>current?.labels(),end:()=>current?.end(),fit:()=>current?.fit()};return controller;
}